#include "mw_alias.h"
#include <string.h>
static uint32_t read32(const unsigned char *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static void put32(unsigned char *p,uint32_t n){for(unsigned i=0;i<4;i++)p[i]=(unsigned char)(n>>(8*i));}
static uint32_t crc(const unsigned char *p,size_t n){uint32_t c=~0u;while(n--){c^=*p++;for(unsigned i=0;i<8;i++)c=(c>>1)^(0xedb88320u&-(c&1u));}return ~c;}
static uint32_t save_crc(const unsigned char *p){unsigned char b[MW_ALIAS_SAVE_BYTES];memcpy(b,p,sizeof(b));memset(b+16,0,4);return crc(b,sizeof(b));}
static unsigned lower(unsigned c){return c>='A'&&c<='Z'?c+32:c;}
static bool equal(const char *a,const char *b){while(*a&&*b){if(lower((unsigned char)*a++)!=lower((unsigned char)*b++))return false;}return *a==*b;}
static bool name_valid(const char *n){if(!n||!*n||*n==' ')return false;unsigned i=0;for(;i<MW_ALIAS_NAME_BYTES&&n[i];i++){unsigned c=(unsigned char)n[i];if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c==' '||c=='_'||c=='-'))return false;}return i<MW_ALIAS_NAME_BYTES&&n[i-1]!=' ';}
static int find(const MwAliasStore *s,uint32_t id){if(!s||s->count>MW_ALIAS_CAPACITY)return -1;for(unsigned i=0;i<s->count;i++)if(s->aliases[i].id==id)return (int)i;return -1;}
static bool valid(const MwAliasStore *s){if(!s||s->count>MW_ALIAS_CAPACITY||(!s->count&&s->selected)||(s->count&&find(s,s->selected)<0))return false;for(unsigned i=0;i<s->count;i++){if(!s->aliases[i].id||!name_valid(s->aliases[i].name))return false;for(unsigned j=0;j<i;j++)if(s->aliases[i].id==s->aliases[j].id||equal(s->aliases[i].name,s->aliases[j].name))return false;}return true;}
bool mw_alias_create(MwAliasStore *s,const char *name){if(!valid(s)||!name_valid(name)||s->count==MW_ALIAS_CAPACITY)return false;uint32_t id=1;for(unsigned i=0;i<s->count;i++){if(equal(name,s->aliases[i].name)||s->aliases[i].id==UINT32_MAX)return false;if(id<=s->aliases[i].id)id=s->aliases[i].id+1;}MwAlias *a=&s->aliases[s->count++];memset(a,0,sizeof(*a));a->id=id;strcpy(a->name,name);s->selected=id;return true;}
bool mw_alias_rename(MwAliasStore *s,uint32_t id,const char *name){int i=find(s,id);if(!valid(s)||i<0||!name_valid(name))return false;for(unsigned j=0;j<s->count;j++)if(j!=(unsigned)i&&equal(name,s->aliases[j].name))return false;char copy[MW_ALIAS_NAME_BYTES];strcpy(copy,name);memset(s->aliases[i].name,0,MW_ALIAS_NAME_BYTES);strcpy(s->aliases[i].name,copy);return true;}
bool mw_alias_select(MwAliasStore *s,uint32_t id){if(!valid(s)||find(s,id)<0)return false;s->selected=id;return true;}
bool mw_alias_remove(MwAliasStore *s,uint32_t id){int i=find(s,id);if(!valid(s)||i<0)return false;for(unsigned j=(unsigned)i+1;j<s->count;j++)s->aliases[j-1]=s->aliases[j];memset(&s->aliases[--s->count],0,sizeof(MwAlias));if(s->selected==id)s->selected=s->count?s->aliases[0].id:0;return true;}
const char *mw_alias_selected_name(const MwAliasStore *s){int i=find(s,s?s->selected:0);return i<0?"NO ALIAS":s->aliases[i].name;}
bool mw_alias_encode(const MwAliasStore *s,unsigned char *out,size_t n){if(!valid(s)||!out||n!=MW_ALIAS_SAVE_BYTES)return false;memset(out,0,n);memcpy(out,"NFA1",4);put32(out+4,1);put32(out+8,s->count);put32(out+12,s->selected);for(unsigned i=0;i<s->count;i++){put32(out+32+i*40,s->aliases[i].id);memcpy(out+36+i*40,s->aliases[i].name,strlen(s->aliases[i].name));}put32(out+16,save_crc(out));return true;}
bool mw_alias_decode(MwAliasStore *s,const unsigned char *in,size_t n){if(!s||!in||n!=MW_ALIAS_SAVE_BYTES||memcmp(in,"NFA1",4)||read32(in+4)!=1||read32(in+8)>MW_ALIAS_CAPACITY||read32(in+16)!=save_crc(in))return false;for(unsigned i=20;i<32;i++)if(in[i])return false;MwAliasStore next={.count=read32(in+8),.selected=read32(in+12)};for(unsigned i=0;i<MW_ALIAS_CAPACITY;i++){const unsigned char *p=in+32+i*40;if(i<next.count){next.aliases[i].id=read32(p);memcpy(next.aliases[i].name,p+4,32);if(!memchr(p+4,0,32))return false;for(unsigned j=4+(unsigned)strlen(next.aliases[i].name);j<40;j++)if(p[j])return false;}else for(unsigned j=0;j<40;j++)if(p[j])return false;}if(!valid(&next))return false;*s=next;return true;}
